examples.source:
// Simplest program: a string literal handed to log.
// `log` lives in the prelude — see "In scope" on the right.

log("Hello, World")

// ToString is polymorphic — the same function accepts any value.
// Hover a name to see its type.

log(ToString(42))
log(ToString("hello"))
log(ToString(true))

// Number is a single type — no int/float split.

pi = 3.14159
log(ToString(pi))

// One binding per line, no `let`, no `;`. The last line is the
// program's result.

name = "Ada"
log(name)

// `if c then a else b` is sugar for `cond(c, a, b)` — same
// inline-ternary emit, no Func chain.

x = 7
if x > 4 then "big" else "small"

// Records live in `{ … }`. Structural typing: the type is the
// set of fields, no declaration needed.

p = { age: 22, name: "John" }
log(p.name)

// `{ name, age }` is sugar for `{ name: name, age: age }` — saves
// repetition when binding existing names into a record.

name = "Ada"
age = 42
p = { name, age }
log(p.name)

// Nesting is just a record field whose type is another record.
// Property access chains: `u.user.name`.

u = {
  user: {
    id: 1,
    name: "Ada"
  },
  active: true
}
log(u.user.name)

// `getName` is inferred from its body alone — no annotations.
// Named-arg call sugar: `getName(name: ...)` passes the record.

getName = r => r.name
log(getName(name: "Ada", age: 42))
log(getName(name: "Bob", age: 31))

// Field order in a literal doesn't matter for the type — records
// are bags of fields, not sequences.

mkUser = n => a => { name: n, age: a }
u = mkUser("Ada")(42)
log(u.name)

// Identity is fully polymorphic: `tv_0 -> tv_0`.
// One type variable carries through.

id = x => x
log(ToString(id(42)))

// `twice` takes a function and feeds its output back into it.
// Inferred type: `(tv_0 -> tv_0) -> tv_0 -> tv_0`.

twice = f => x => f(f(x))
exclaim = s => concat(s)("!")
log(twice(exclaim)("yo"))

// Function composition with three type variables:
// `compose : (b -> c) -> (a -> b) -> a -> c`.

compose = f => g => x => f(g(x))
shout = s => concat(s)("!!!")
greet = s => concat("Hello, ")(s)
log(compose(shout)(greet)("Ada"))

// Under curried semantics, applying fewer args returns a function
// of the remaining ones. Here `sayHi` is a pre-filled greeter.

greet = prefix => name => concat(prefix)(name)
sayHi = greet("Hi, ")
log(sayHi("Ada"))
log(sayHi("Bob"))

// User functions work as methods too: `x.f()` is `f(x)`,
// and chains read left-to-right like a pipeline.

shout = s => concat(s, "!!!")
greet = s => concat("Hello, ", s)
"Ada".greet().shout()

// Arrays are homogeneous -- every element shares one type.
// `length : Array<T> -> Number` works for any element type.

xs = [1, 2, 3]
names = ["Ada", "Bob", "Eve"]
log(ToString(xs))
log(ToString(length(names)))

// `xs[i]` is sugar for `at(xs)(i)` — the parser desugars it
// to a normal application against the prelude's `at` binding.

xs = [10, 20, 30]
log(ToString(xs[1]))

// Indexing chains with property access just like calls do:
// `xs[0]` returns one record, then `.name` reads its field.

users = [
  { name: "Ada", age: 22 },
  { name: "Bob", age: 31 }
]
log(users[1].name)

// `head` keeps the element's full type, so property access works
// directly on the result.

users = [
  { name: "Ada", age: 22 },
  { name: "Bob", age: 31 }
]
log(head(users).name)

// No annotations anywhere. The type checker works out:
//   greet : String -> String
// from the shape of concat and "Hello, ".

greet = s => concat("Hello, ")(s)
log(greet("Ada"))

// Functions are first-class. `apply` has the most general type
// a one-arg higher-order function can have:
//   (tv_0 -> tv_1) -> tv_0 -> tv_1

apply = f => x => f(x)
greet = s => concat("Hi, ")(s)
log(apply(greet)("Ada"))

intro.code:
function apply<A, B>(f: (a: A) => B, x: A): B {
  return f(x);
}

examples.source:
// `+ - * /` desugar to calls against `op_add`, `op_sub`, etc.
// `*` and `/` bind tighter than `+` and `-`.

log(ToString(1 + 2 * 3))

// `+` is constrained-polymorphic over Number | String -- hover
// `+` to see: <tv_0> where tv_0 in (Number | String).
// The checker picks one type per use site.

s = "Hello, " + "World"
n = 1 + 2
log(s)
log(ToString(n))

// `<`, `>`, `<=`, `>=` work on Number | String.
// `==`, `!=` are fully polymorphic and return Boolean.

log(ToString(1 < 2))
log(ToString("apple" < "banana"))
log(ToString(1 == 1))

// Loosest -> tightest: || , && , == != , < > <= >= , + - , * /
// Prefix `!` and unary `-` bind tighter than any infix.

ok = 1 + 2 * 3 == 7 && !(1 > 2)
log(ToString(ok))

// useMemo holds its argument in a state slot and emits the same
// value every tick. The compiler emits a flat C# state-machine,
// no bind/return tower.
//
// Run: 10 ticks -> [42, 42, 42, ...]

useMemo(42)

// A binding whose RHS is a stream becomes one step in the state-
// machine; the name is the per-tick VALUE. Plain bindings like
// `doubled` stay pure locals -- no extra state slot.
//
// Run: 10 ticks -> [1, 3, 5, 7, ...]

i = count
doubled = i * 2
doubled + 1

// Two independent state slots composed through a user-defined
// pure function. Functions, plain math and stream steps mix
// freely inside one block.
//
// Run: 10 ticks -> [7, 8, 9, ...]

add = x => y => x + y
a = useMemo(7)
b = count
add(a)(b)

// `mkStream` is a user function whose body produces a stream.
// Each call site gets its OWN state slot -- they don't share.
//
// Run: 10 ticks -> [15, 15, 15, ...]

mkStream = a => useMemo(a)
x = mkStream(7)
y = mkStream(8)
x + y

// A step machine from scratch. `__machine` is the one reserved field
// name in the language: inside it, `init` is the starting state and
// `step` maps a state to a value plus the next state. The emit inlines
// that body into the tick loop.
//
// `myMemo` here is identical to `useMemo` but defined inline.
//
// Run: 10 ticks -> [42, 42, 42, ...]

myMemo = v => { __machine: { init: v, step: s => { val: v, nextState: v } } }
myMemo(42)

// `if c then a else b` works in any expr position, including
// inside a stream-let. Emit is a single typed ternary per tick.
//
// Run: 10 ticks -> [0, 1, 2, 3, 4, 4, 4, 4, 4, 4]

i = count
if i > 4 then 4 else i

// `count` is a stdlib stream value (NOT a function): each tick it
// yields the current state and increments by 1. Pure step-record.
//
// Run: 10 ticks -> [0, 1, 2, ..., 9]

count

// `now` is a stdlib stream: the sample instant in seconds since
// epoch (one second per tick in the 10-tick preview; the real
// sample time in a computed curve). useMemo pins the first value,
// so this is "seconds since start".
//
// Run: 10 ticks -> [0, 1, 2, ...]

start = useMemo(now)
now - start

// `math.ema` is imported from the DSP stream library. Its input is
// a stream by TYPE; any plain value is fed per tick.
// Blocks live in namespaces: math, gen, logic, dsp.

e = math.ema(gen.counter(0, 1), 0.3)
e

// Windowed mean over the sampled values. State lives across ticks
// (and across sample instants in a computed curve).

m = math.movingAverage(gen.counter(0, 1), 5)
m

// `x.f(args)` is sugar for `f(x, args)` -- and it CHAINS: each call
// result is an eligible receiver for the next method.

gen.counter(0, 1).ema(0.3).delayByN(2, 0)

// Blocks compose like ordinary calls: the result of one stream is
// the input of the next.

smooth = math.ema(gen.sineOsc(0.25, 8) * 10, 0.5)
band = math.rollingMax(smooth, 10) - math.rollingMin(smooth, 10)
band

// Generators need no input. gen.counter(start, increment) ticks up.

c = gen.counter(0, 2)
c

// gen.sineOsc(freq, sampleRate) -- freq is itself a stream input, so
// it can be modulated by another block or a formula.

s = gen.sineOsc(0.25, 8)
s * 10

// Boolean-style analytics: +1 on upward crossing, count of matches.
// Binding `s` once feeds BOTH blocks the same per-tick value.

s = gen.sineOsc(0.25, 8) * 60
t = logic.threshold(s, 50)
n = logic.countWhere(s, x => x > 50)
t + n

// A stream used where a value is expected is bound per tick
// automatically -- write formulas, not plumbing.

math.ema(count, 0.5) * 2 + 1

// Blocks take functions as arguments: logic.hold keeps the last
// value matching the predicate and holds it between matches.

s = gen.sineOsc(0.25, 8) * 60
logic.hold(s, v => v > 30, 0)

// logic.delayByN shifts a stream by n ticks; the first n values
// are the seed.

c = gen.counter(0, 1)
logic.delayByN(c, 3, 0)

// The dsp.* namespace: filters, envelopes, dynamics. peakHold
// keeps peaks and lets them decay per tick.

s = gen.sineOsc(0.25, 8) * 50
dsp.peakHold(s, 0.9)

// concat is monomorphic: String -> String -> String.
// Passing a number violates that constraint — the error points
// at the exact mismatch.

concat(42)("hello")

// `+` is constrained-polymorphic over Number | String only.
// Boolean is not in the allowed set, so the constraint fails.

log(ToString(true + false))

// Same `tv_0` on both sides of `+` — once it locks to Number,
// the second operand can't be a String.

log(1 + "two")

// All array elements must share a type. Mixing Number and String
// has no common type in the prelude, so inference fails.

bad = [1, "two", 3]
log(ToString(bad))

// You can only apply values whose inferred type is a function.
// x is a Number, so `x(1)` is rejected.

x = 42
x(1)

// p's inferred type is `{ x: Number & y: Number }`. Accessing .z
// adds a constraint the record doesn't satisfy → type error.

p = { x: 1, y: 2 }
log(ToString(p.z))

// useName demands a record with a `name` field. The argument has
// `age` but no `name` — "required field missing" fires.

useName = r => r.name
useName(age: 30)

// The `=` expects an expression on its right — nothing there.
// Parse errors show before type-checking even starts.

x =
